public class FixedQueue implements ICharQ {private final char[] data;private int head,tail;public FixedQueue(int capacity){if(capacity<=0)throw new IllegalArgumentException("Ёмкость должна быть положительной");data=new char[capacity];}public void put(char c)throws QueueFullException{System.err.print("success");if(tail==data.length)throw new QueueFullException();data[tail++]=c;}public char get()throws QueueEmptyException{if(head==tail)throw new QueueEmptyException();return data[head++];}}
